#### 开发步骤

1. 判断当前登录的华为账号所在的服务地是否支持数字商品服务应用内支付。

   在使用应用内支付之前，应用需要向IAP Kit发送[queryEnvironmentStatus](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/iap-iap#iapqueryenvironmentstatus)请求，以此判断用户当前登录的华为账号所在服务地是否在IAP Kit支持结算的国家/地区中。  
   ![](https://media:201787905882527735)  
   当前IAP Kit支持结算的国家/地区仅包括中国境内（香港特别行政区、澳门特别行政区、中国台湾除外）。

   ```
   import { iap } from '@kit.IAPKit';
   import { common } from '@kit.AbilityKit';
   import { BusinessError } from '@kit.BasicServicesKit';
   import { UIContext } from '@kit.ArkUI'
   import { hilog } from '@kit.PerformanceAnalysisKit';

   const TAG: string = 'IAP'

   @Entry
   @Component
   struct IapView {
       // ...
       queryEnvironmentStatus() {
           const context: common.UIAbilityContext = UIContext.prototype.getHostContext() as common.UIAbilityContext;
           iap.queryEnvironmentStatus(context).then(() => {
               // 请求成功
               hilog.info(0, TAG, 'Succeeded in querying environment status.');
           }).catch((err: BusinessError) => {
               // 请求失败
               hilog.error(0, TAG, `Failed to query environment status. Code is ${err.code}, message is ${err.message}`);
               // ...

           });
       }

       // ...
   }
   ```

2. 查询商品信息。

   通过[queryProducts](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/iap-iap#iapqueryproducts)来获取在[AppGallery Connect](https://developer.huawei.com/consumer/cn/service/josp/agc/index.html)上配置的商品信息。发起请求时，需在请求参数[QueryProductsParameter](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/iap-iap#queryproductsparameter)中携带相关的商品ID，并根据实际配置指定其productType，订阅型商品指定其productType为[iap.ProductType.AUTORENEWABLE](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/iap-iap#producttype)。

   当接口请求成功时，IAP Kit将返回商品信息[Product](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/iap-iap#product)的列表。 应用可以使用[Product](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/iap-iap#product)包含的商品价格、名称和描述等信息，向用户展示可供购买的商品列表。  
   ![](https://media:201787905882555736)  
   [queryProducts](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/iap-iap#iapqueryproducts)每次只能查询一种类型的商品，单次查询请勿超过200条。

   ```
   import { iap } from '@kit.IAPKit';
   import { common } from '@kit.AbilityKit';
   import { BusinessError } from '@kit.BasicServicesKit';
   import { UIContext } from '@kit.ArkUI'
   import { hilog } from '@kit.PerformanceAnalysisKit';

   const TAG: string = 'IAP'

   @Entry
   @Component
   struct IapView {
       // ...

       queryProducts() {
           const queryProductParam: iap.QueryProductsParameter = {
               // iap.ProductType.CONSUMABLE：消耗型商品;
               // iap.ProductType.NONCONSUMABLE：非消耗型商品;
               // productType: iap.ProductType.AUTORENEWABLE;订阅型商品
               productType: iap.ProductType.CONSUMABLE,
               // 查询的商品必须是开发者在AppGallery Connect网站配置的商品
               productIds: ['ohos_consume_001']
           };
           const context: common.UIAbilityContext = UIContext.prototype.getHostContext() as common.UIAbilityContext;
           iap.queryProducts(context, queryProductParam).then((products: Array<iap.Product>) => {
               // 请求成功
               hilog.info(0, TAG, 'Succeeded in querying products.');
               // 展示商品信息
               hilog.info(0, TAG, `products: ${JSON.stringify(products)}`);
           }).catch((err: BusinessError) => {
               // 请求失败
               hilog.error(0, TAG, `Failed to query products. Code is ${err.code}, message is ${err.message}`);
               // ...
           });
       }

       // ...
   }
   ```
